async def resolve_github_clone_access_via_broker(
    control_url: str,
    runner_token: str,
    remote_url: str,
) -> dict | None:
    """Resolve GitHub clone access via the broker client."""
    from yinshi.models import RunnerGitHubAccessOut

    url = f"{control_url.rstrip('/')}/runner/github-access"
    headers = {
        "Authorization": f"Bearer {runner_token}",
        "Content-Type": "application/json",
    }
    async with httpx.AsyncClient(
        limits=httpx.Limits(max_connections=2, max_keepalive_connections=1),
        timeout=httpx.Timeout(10.0, connect=5.0),
    ) as client:
        try:
            response = await client.post(url, json={"remote_url": remote_url}, headers=headers)
        except httpx.TimeoutException:
            logger.warning("Broker timeout during GitHub access resolution")
            raise RuntimeError("GitHub integration error") from None
        except httpx.RequestError:
            logger.warning("Broker connection error during GitHub access resolution")
            raise RuntimeError("GitHub integration error") from None
        except httpx.HTTPStatusError:
            logger.warning("Broker HTTP error during GitHub access resolution")
            raise RuntimeError("GitHub integration error") from None

        if response.status_code == 200:
            if response.text == "null":
                return None
            try:
                data = response.json()
                RunnerGitHubAccessOut.model_validate(data)
                return data
            except Exception:
                logger.warning("Broker returned invalid response")
                raise RuntimeError("GitHub integration error") from None
        elif response.status_code == 400:
            detail = response.json().get("detail", {})
            logger.warning(
                "GitHub access denied: code=%s message=%s",
                detail.get("code"),
                detail.get("message"),
            )
            raise RuntimeError(
                f"GitHub access error: {detail.get('message', 'unknown')}"
            ) from None
        elif response.status_code >= 500:
            logger.warning("Broker server error during GitHub access resolution")
            raise RuntimeError("GitHub integration error") from None
        else:
            logger.warning(
                "Unexpected broker response status: %d",
                response.status_code,
            )
            raise RuntimeError("GitHub integration error") from None


