async def _request_runner_github_access(
    client: httpx.AsyncClient,
    runner_token: str,
    remote_url: str,
) -> GitHubCloneAccess | None:
    """Resolve GitHub clone access via the runner control-plane broker."""
    if not runner_token:
        raise GitHubAppError("runner token must not be blank")
    if not remote_url:
        raise GitHubAppError("remote_url must not be blank")

    base_url = client.base_url
    if isinstance(base_url, (bytes, str)):
        url = f"{str(base_url).rstrip('/')}/runner/github-access"
    else:
        url = f"{client.base_url.raw_path.decode('utf-8').rstrip(b'/').decode('utf-8')}/runner/github-access"

    headers = {
        "Authorization": f"Bearer {runner_token}",
        "Content-Type": "application/json",
    }

    try:
        response = await client.post(url, json={"remote_url": remote_url}, headers=headers)
    except httpx.TimeoutException:
        raise GitHubAppError("GitHub integration error") from None
    except httpx.RequestError:
        raise GitHubAppError("GitHub integration error") from None

    if response.status_code >= 500:
        raise GitHubAppError("GitHub integration error") from None
    if response.status_code == 400:
        try:
            detail = response.json()
        except Exception:
            detail = {}
        raise GitHubAccessError(
            message=detail.get("message", str(detail)),
            code=detail.get("code", "access_error"),
            connect_url=detail.get("connect_url"),
            manage_url=detail.get("manage_url"),
        ) from None
    if response.status_code != 200:
        raise GitHubAppError("GitHub integration error") from None

    text = response.text[:MAX_RESPONSE_BYTES]
    if text.strip() == "null":
        return None
    try:
        data = json.loads(text)
    except (json.JSONDecodeError, ValueError):
        raise GitHubAppError("GitHub integration error") from None
    try:
        parsed = RunnerGitHubAccessOut.model_validate(data)
    except Exception:
        raise GitHubAppError("GitHub integration error") from None
    return GitHubCloneAccess(
