describe("RunnerRpcError API compatibility", () => {
  it("is instanceof both RunnerRpcError and ApiError and preserves all fields", () => {
    import("./encryptedRunnerClient").then((mod) => {
      const { RunnerRpcError } = mod;
      const error = new RunnerRpcError(400, {
        detail: {
          code: "install_not_found",
          message: "Repository not installed",
          connect_url: "https://github.com/apps/yinshi",
          manage_url: "https://github.com/settings/installations",
        },
      });
      expect(error).toBeInstanceOf(RunnerRpcError);
      expect(error).toBeInstanceOf(mod.ApiError);
      expect(error.status).toBe(400);
      expect(error.body).toEqual({
        detail: {
          code: "install_not_found",
          message: "Repository not installed",
          connect_url: "https://github.com/apps/yinshi",
          manage_url: "https://github.com/settings/installations",
        },
      });
      expect(error.message).toBe("install_not_found: Repository not installed");
      expect(error.code).toBe("install_not_found");
      expect(error.connectUrl).toBe("https://github.com/apps/yinshi");
      expect(error.manageUrl).toBe("https://github.com/settings/installations");
      expect(error.name).toBe("RunnerRpcError");
    });
  });
});

