  readonly body: unknown;

  constructor(status: number, body: unknown) {
    const parsed = body && typeof body === "object" ? (body as Record<string, unknown>).detail : undefined;
    const structured = parsed && typeof parsed === "object" ? (parsed as Record<string, unknown>) : undefined;
    const code = typeof structured?.code === "string" ? structured.code : undefined;
    const message = typeof structured?.message === "string" ? structured.message : `Runner RPC failed with status ${status}`;
    super(status, code ? `${code}: ${message}` : message, structured as any);
    this.name = "RunnerRpcError";
    this.body = body;
  }
}

